(function(root,factory){const common=typeof module==='object'&&module.exports;const api=factory(common?require('./engine.js'):root.TravellerEngine,common?require('./english.js'):root.TravellerEnglish,common?require('./world-engine.js'):root.TravellerWorld);if(common)module.exports=api;else{root.TravellerMinimal=api;if(!root.document.documentElement.hasAttribute('data-scene-ui'))api.mount(root.document)}})(typeof globalThis==='object'?globalThis:this,function(E,L,W){
'use strict';
const KEY='traveller-first-term-v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const en=(v,fallback)=>esc(L.english(v,fallback));
const money=n=>'Cr'+Number(n||0).toLocaleString('en-GB');
const sign=E.signed;
const careerLabel=g=>E.career(g).name;
const events={
2:['Disaster.','An expedition goes badly wrong. Resolve a Mishap, but this event does not force you out of the Scouts.'],
3:['Ambush.','Enemy vessels intercept your ship. Run for safety or attempt to bargain. Failure destroys your ship and ends your Scout career after this term. Either way, gain an Enemy.'],
4:['An alien world.','Surveying an unfamiliar world teaches you something new. Choose one skill at level 1.'],
5:['Exemplary service.','Your work earns recognition. Keep a +1 DM for one Other Benefits roll when you leave the Scouts.'],
6:['World after world.','Years of jumps and distant ports leave you with practical experience. Choose one skill at level 1.'],
7:['Life goes on.','Something outside your service changes your life. Roll on the Life Events table.'],
8:['Alien intelligence.','You have a chance to learn more about an alien race. Choose Sensors or Deception. Success earns an Ally and +2 DM to your next Advancement check. Failure causes a Mishap without ejecting you from the career.'],
9:['First to respond.','Your ship reaches the survivors of a disaster. Help through Medic or Engineer. Success earns a Contact and +2 DM to Advancement; failure earns an Enemy.'],
10:['On the frontier.','Time on the edge of known space tests your resourcefulness. Success earns an alien Contact and one skill level of your choice. Failure causes a Mishap.'],
11:['An important message.','You carry a message for the Imperium. Choose Diplomat 1 or +4 DM to your next Advancement check.'],
12:['A valuable discovery.','Your discovery matters to the Imperium. Gain a Rank, then make the normal Advancement check.']};
const navyEvents={2:['Disaster.','Resolve a Navy Mishap, but remain in the career.'],3:['Shipboard gambling.','Gain Gambler 1 or Deception 1. You may also risk a Gambler 8+ check for an extra Benefit roll; failure loses one.'],4:['Special assignment.','Gain DM+1 to one Benefit roll.'],5:['Specialist training.','Make an Education 8+ check to increase one existing skill.'],6:['Combat action.','Gain Sensors 1, Engineer 1, Gunner 1 or Pilot 1.'],7:['Life Event.','Roll on the Life Events table.'],8:['Diplomatic mission.','Gain Recon 1, Diplomat 1, Steward 1 or a Contact.'],9:['Crime prevented.','Gain an Enemy and DM+2 to the next Navy Advancement check.'],10:['Abuse of position.','Take an extra Benefit roll, or refuse and gain DM+2 to Advancement.'],11:['Command attention.','Gain Tactics (naval) 1 or DM+4 to Advancement.'],12:['Heroism in battle.','Gain an automatic promotion or Commission, then make the normal career progression check.']};
const life={2:['Injury or illness.','Roll on the Injury table.'],3:['Birth or death.','Someone close to you is born, or someone close to you dies. Choose how this enters your history.'],4:['A relationship ends.','A romantic relationship ends.'],5:['A deeper commitment.','A relationship becomes stronger, perhaps leading to marriage.'],6:['A new relationship.','You become involved in a romantic relationship.'],7:['A new Contact.','You make a new Contact.'],8:['Betrayal.','Someone you trusted turns against you. Change an existing Contact or Ally into a Rival or Enemy, or create one if you have none.'],9:['Travel.','You move to another world. Keep +2 DM to your next Qualification check.'],10:['Good fortune.','Something goes your way. Keep +2 DM to one Benefit roll.'],11:['Crime.','A crime affects your life. Lose one Benefit roll or reduce Social Standing by 1.'],12:['Something unusual.','Roll 1d6 to discover what happened.']};
const mishaps={1:['Severely injured.','Apply result 2 on the Injury table, or roll twice and take the lower result.'],2:['Psychological damage.','Reduce Intelligence or Social Standing by 1.'],3:['Stranded.','Your damaged ship leaves you hitch-hiking to a Scout base. Gain 1d6 Contacts and 1d3 Enemies.'],4:['An unintended conflict.','Your actions provoke a conflict. Gain a Rival and Diplomat 1.'],5:['Missing memories.','Your ship is found drifting. You cannot remember what happened.'],6:['Injured.','Roll on the Injury table.']};
const injuries={1:'Nearly killed.',2:'Severely injured.',3:'An eye or limb lost.',4:'Scarred and injured.',5:'Injured.',6:'Lightly injured.'};
const tableNames={personal:'Personal Development',service:'Service Skills',assignment:'Specialist Skills',education:'Advanced Education',officer:'Officer Skills'};
function heading(label,title,body=''){return `<p class="eyebrow">${esc(label)}</p><h1>${title}</h1>${body?`<p class="description">${body}</p>`:''}`}
function button(g,label,type='next',value,primary=true){return `<button type="button" class="${primary?'primary':'plain'}" data-key="action-${type}-${esc(value??'')}" data-command="${type}" data-revision="${g.revision}" ${value!==undefined?`data-value="${esc(value)}"`:''}>${label}</button>`}
function next(g,label='Continue',disabled=false){return `<div class="actions">${disabled?`<button class="primary" disabled>${label}</button>`:button(g,label)}</div>`}
function choose(g,options=E.choices(g)){return `<div class="choices">${options.map(o=>`<button type="button" data-key="choice-${esc(o.id)}" data-command="select" data-value="${esc(o.id)}" data-revision="${g.revision}" class="choice" ${o.disabled?'disabled':''}><span>${en(o.label,'Choose this option')}</span>${o.description?`<small>${choiceDescription(g,o)}</small>`:''}</button>`).join('')}</div>`}
function choiceDescription(g,o){if(o.description)return en(o.description);if(g.phase==='eventchoice'&&o.skill)return `${en(o.skill)} ${o.target}+ · ${L.short[o.attribute]} DM ${sign(E.dm(g.stats[o.attribute]))}${o.skill==='__education__'?'':' · skill '+sign(E.skillModifier(g,o.skill))}`;if(g.phase==='benefitweapon'){const w=E.WEAPONS.find(w=>w.id===o.id);return w?en(w.skill):'Increase the relevant skill for an earlier Weapon benefit.';}return ''}
function preview(kind,g){if(!g.currentRoll)return '';const r=g.currentRoll;let item;if(kind==='event')item=events[r.raw];if(kind==='life')item=life[r.raw];if(kind==='mishap')item=mishaps[r.raw];if(kind==='injuryroll'||kind==='injurydouble')return `<p class="result-description">${injuries[kind==='injurydouble'?r.selected:r.raw]}</p>`;if(kind==='unusual')item=({1:['Psionics Institute.','You may test Psionic Strength or decline.'],2:['Among aliens.','Gain Life Science (biology) and an alien Contact.'],3:['An alien artefact.','You acquire an unusual alien object.'],4:['Amnesia.','Something happened, but you cannot remember it.'],5:['Imperial connections.','You briefly meet the highest levels of the Imperium.'],6:['Ancient technology.','You acquire something older than the Imperium.']})[r.raw];if(kind==='trainingroll'){const entry=E.tableRows(g,g.context.table)[r.raw-1];return `<p class="result-description">${en(E.rewardLabel(entry))}</p>`}if(kind==='benefitroll'){const row=Math.max(1,Math.min(7,r.total));return `<p class="result-description">${g.benefits.type==='cash'?money([20000,20000,30000,30000,50000,50000,50000][row-1]):['1 Ship Share','Int +1','Edu +1','Weapon','Weapon','Scout Ship','Scout Ship'][row-1]}</p>`}return item?`<div class="event-copy"><h2>${item[0]}</h2><p>${item[1]}</p></div>`:''}
function roll(g,kind=g.phase,label='Continue'){const r=g.currentRoll;const single=['trainingroll','mishap','injuryroll','injurydamage','unusual','crisisroll','benefitroll','benefitshares'].includes(kind);let spec;try{spec=E.check(g,kind)}catch{}const formula=spec?`<p class="formula">2d6 ${spec.parts.map(p=>`${sign(p.value)} ${en(p.label)}`).join(' ')} ≥ ${spec.target}</p>`:'';return formula+`<section class="roll" data-key="roll-${kind}">${r?`<p class="dice-result" role="status">${r.dice.join(' + ')}${r.modifier?' '+sign(r.modifier):''} = ${r.total}${r.selected!==undefined?' · take '+r.selected:''}${r.success!==undefined?' · '+(r.success?'Success':'Failure'):''}</p>${preview(kind,g)}`:button(g,'Roll '+(single?'1d6':'2d6'),'roll',undefined,false)}</section>`+next(g,label,!r)}
function characteristicLine(g){return g.stats?`<dl class="characteristics">${L.short.map((n,i)=>`<div data-key="stat-${i}"><dt title="${L.statNames[i]}">${n}</dt><dd>${g.stats[i]}<small>${sign(E.dm(g.stats[i]))}</small></dd></div>`).join('')}</dl>`:''}
function skillList(g){return `<dl class="listing">${Object.entries(g.skills).map(([name,level])=>`<div data-key="skill-${esc(name)}"><dt>${en(name)}</dt><dd>${level}</dd></div>`).join('')}</dl>`}
function summary(g){const f=g.finalFunds;return heading('Character complete',`${esc(g.name||'Your Traveller')}.`,'Human · '+esc(g.homeworld?.name||'Homeworld')+'. Your career history is ready to take into play.')+`<p class="identity">Age ${g.age} · ${g.totalTerms} terms · ${g.careerHistory.length} careers</p><h2>Skills</h2>${skillList(g)}<h2>Benefits</h2><dl class="listing"><div><dt>Cash</dt><dd>${money(f.cash)}</dd></div><div><dt>Debt</dt><dd>${money(f.debt)}</dd></div><div><dt>Annual pension</dt><dd>${money(g.pension||0)}</dd></div><div><dt>Ship Shares</dt><dd>${g.shares}</dd></div></dl>${g.assets.length?`<ul class="text-list">${g.assets.map(v=>`<li>${en(v,'An item recorded in your inventory.')}</li>`).join('')}</ul>`:''}${g.relations.length?`<h2>Contacts and connections</h2><ul class="text-list">${g.relations.map(r=>`<li>${en(r.name,'Acquaintance')} · ${en(r.type)}</li>`).join('')}</ul>`:''}${g.psi!==undefined?`<p>Psionic Strength ${g.psi}.</p>`:''}<p class="note">Connections, campaign skills and starting equipment are recorded in this character.</p><p><button class="plain" data-command="finishing-open" data-revision="${g.revision}">Review Connections and campaign skills</button></p><div class="actions"><button type="button" class="primary" data-ui="print">Print character</button><button type="button" class="plain" data-ui="new">New character</button></div>`}
function worldView(g){const w=['worldgen','worldreview'].includes(g.phase)?g.world||g.homeworld:g.homeworld||g.world;if(!w)return '';if(!w.complete)return `<section class="homeworld-record"><p class="eyebrow">Homeworld record</p><p>Generation in progress · ${esc(W.stepInfo(w)[0])}</p></section>`;const d=W.describe(w);return `<section class="homeworld-record" data-key="homeworld-record"><p class="eyebrow">Homeworld record</p><div class="world-title"><h2>${esc(w.name||'Unnamed world')}</h2><code>${esc(w.uwp)}</code><span>${esc(w.travelCode)} Zone</span></div>${w.description?`<p>${esc(w.description)}</p>`:''}<dl class="world-facts">${w.temperatureType?`<div><dt>Climate</dt><dd>${esc(w.temperatureType)}</dd></div>`:''}<div><dt>Size</dt><dd>${w.size}</dd></div><div><dt>Atmosphere</dt><dd>${w.atmosphere}</dd></div><div><dt>Hydrographics</dt><dd>${w.hydrographics}</dd></div><div><dt>Population</dt><dd>${w.population}</dd></div><div><dt>Government</dt><dd>${esc(d.government)}</dd></div><div><dt>Law</dt><dd>${w.law}</dd></div><div><dt>Starport</dt><dd>${esc(w.starport)}</dd></div><div><dt>Tech Level</dt><dd>${w.tech}</dd></div></dl><p>${w.tradeCodes.map(t=>`${esc(t.code)} · ${esc(t.name)}`).join(' · ')||'No Trade Classifications'}${w.bases.length?' · Bases: '+w.bases.map(b=>esc(b.name)).join(', '):''}</p><p>Culture: ${esc(w.culture||'None recorded')}${d.factions.length?' · Factions: '+d.factions.map(f=>`${esc(f.strengthName)} ${esc(f.governmentName)}`).join(', '):''}</p></section>`}
function view(g,draft=''){const p=g.phase;const term=`Term ${g.term} · age ${g.age}`;
switch(p){case 'psichoice':return heading('Psionics · Life Event','The Psionics Institute.','This Life Event encounter opens the path. Testing costs Cr5,000 and takes two weeks. The result cannot be rerolled.')+choose(g);
case 'psitraining':return heading('Psionics Institute','Develop your potential.',`Your Psionic Strength is ${g.psi}. Institute training costs Cr100,000 and takes four months. Potential alone grants no talents.`)+choose(g);
case 'psitalents':return heading('Talent acquisition','Choose what to attempt next.',`Choose the order yourself. Roll 2d6 + Psi DM + Learning DM − previous attempts, against 8+. Success grants level 0. Previous attempts: ${g.psionics.attempts.length}.`)+choose(g);
case 'psilearn':return heading('Talent acquisition',`Acquire ${esc(g.psionics.current.talent)}.`,`Success grants level ${g.psionics.current.level||0}; failure grants nothing. Every attempt, successful or not, adds DM−1 to future acquisition checks.`)+roll(g);
case 'psibasic':return heading(E.career(g).name+' Basic Training','Specialist Skills.','Receive level 0 in your assignment’s Specialist Skills. Psionic talents require a successful acquisition check first.')+next(g);
case 'worldgen':{const [title,body]=W.stepInfo(g.world);return heading('World Creation',title+'.',body)+(W.choices(g.world).length?choose(g):`<p class="note">${g.currentRoll?'The roll is fixed. Apply it to continue.':'The next world characteristic is generated with dice.'}</p>`)}
case 'worldreview':return heading('World Creation','Name the homeworld.','The Universal World Profile and all generated details will remain available throughout character creation.')+worldView(g)+`<label class="first-name" for="world-name">World name<input id="world-name" maxlength="45" autocomplete="off" placeholder="Enter a world name"></label>`;
case 'world':return heading('Character Creation','Who are you?','Your homeworld is recorded. Name the human Traveller whose life you are about to create.')+`<label class="first-name" for="name">Character name<input id="name" maxlength="45" autocomplete="off" value="${esc(draft||g.name)}" placeholder="Enter a name"></label>`;
case 'stats':return heading('Characteristics','Your starting point.','Roll 2d6 six times. Assign each result to one characteristic. Each roll is used once.')+`<label class="name-label" for="name">Name <span class="optional">optional</span><input id="name" data-key="name" autocomplete="off" maxlength="45" value="${esc(draft||g.name)}"></label>`+(!g.statRolls.length?`<div class="actions">${button(g,'Roll characteristics','rollstats')}</div>`:`<div class="assignments">${L.statNames.map((name,i)=>`<label data-key="allocate-${i}" for="allocate-${i}"><span>${name}</span><select id="allocate-${i}" data-allocate="${i}" aria-label="${name}">${g.statRolls.map((r,j)=>`<option value="${j}" ${g.allocation[i]===j?'selected':''}>${r.raw} · roll ${j+1} (${r.dice.join(' + ')})</option>`).join('')}</select><small>DM ${sign(E.dm(g.statRolls[g.allocation[i]].raw))}</small></label>`).join('')}</div>`+next(g));
case 'homeworldskill':return heading('Homeworld Skill','What did this world teach you?','Choose the level-0 skills granted by your homeworld’s Trade Classifications, up to your Background Skill limit.')+choose(g);
case 'background':{const available=Math.max(0,g.backgroundLimit-(g.homeworldSkillsChosen?.length??(g.homeworldSkill?1:0)));return heading('Background Skills','Before your first career.',`Your Education allows ${g.backgroundLimit} Background Skills. ${g.homeworldSkillsChosen?.length?g.homeworldSkillsChosen.map(n=>en(n)+' 0').join(', ')+' come from your homeworld. ':''}Choose ${available} from the education list.`)+`<div class="background-list">${E.SCHOOL.filter(n=>!g.homeworldSkillsChosen?.includes(n)).map(name=>`<label data-key="background-${esc(name)}"><input type="checkbox" data-background="${esc(name)}" ${g.background.includes(name)?'checked':''}><span>${en(name)} 0</span></label>`).join('')}</div><p class="note" role="status">${g.background.length} of ${available} selected.</p>`+next(g,'Continue',g.background.length!==available);}
case 'rankaward':return heading('Rank Benefit','Choose your rank award.','This award comes from your career’s Rank table.')+choose(g);case 'undercover':return heading('Undercover Operation','Choose your cover.','Resolve the Citizen or Rogue table specified by the Agent event.')+choose(g);case 'undercovertraining':return heading('Undercover Training','Choose an assignment.','Roll once on this cover assignment’s Specialist Skills table.')+choose(g);case 'rulesubtable':return heading('Career Table',g.context.subtable.replace(/-/g,' ')+'.','Roll the dice, then resolve the table result.')+roll(g);case 'careerchoice':return heading('Career','Choose a career.','You may attempt one career each term. A career left in the previous term cannot be chosen immediately again.')+choose(g);
case 'enlist':return heading(careerLabel(g),E.career(g).entry.name+'.','Roll 2d6 with the listed characteristic and career DMs. A failed entry leads to the Draft or Drifter.')+roll(g,p,'Resolve entry');
case 'entryfailed':return heading('Career Entry','Entry failed.','Choose the one-time Draft or enter Drifter automatically.')+choose(g);
case 'draftroll':return heading('The Draft','Where are you sent?','Roll 1d6: 1 Navy, 2 Army, 3 Marines, 4 Merchant, 5 Scout, 6 Agent.')+roll(g);
case 'draftunsupported':return heading('The Draft',`Draft result ${g.context.draftResult}.`,'This result points to a career outside the current Scout/Navy content package. The roll is preserved and cannot be rerolled.');
case 'basic':if(E.career(g).specialistBasic)return heading(E.career(g).name+' Basic Training','Choose your assignment next.','This career uses Specialist Skills instead of Service Skills for Basic Training.')+next(g);return heading('Basic Training','Learn the essentials.',g.activeCareer?.careerNumber===1?'Your first career grants every Service Skill at level 0.':'A later career grants one Service Skill at level 0.')+next(g);
case 'laterbasic':if(E.career(g).specialistBasic)return heading(E.career(g).name+' Basic Training','Choose one Specialist Skill.','A later career grants one skill at level 0. Unacquired talents are not granted automatically.')+choose(g);return heading('Basic Training','Choose one Service Skill.','In every career after the first, Basic Training grants one Service Skill at level 0.')+choose(g);
case 'assignment':return heading(term,'Choose an assignment.',`Select your role within the ${careerLabel(g)} career.`)+choose(g);
case 'overview':return heading(term,`${careerLabel(g)} · ${E.choices({...g,phase:'assignment'}).find(x=>x.id===g.assignment)?.label||g.assignment}.`,'A term lasts four years. Train, check Survival, resolve an Event, then check Advancement or Commission.')+`<details data-key="anagathics"><summary>Anagathics${g.anagathics.active?' · taking':''}</summary><p>Anagathics offset Aging, but require a second Survival check and cost 1d6 × Cr2,500 per term. Stopping a course causes an immediate Aging check.</p>${button(g,g.anagathics.active?'Stop taking anagathics':'Start taking anagathics','anagathics',g.anagathics.active?'stop':'start',false)}</details>`+next(g,'Begin term');
case 'training':return heading(term,g.context.trainingBonus?'Additional training.':'Skills and training.',g.context.trainingBonus?'Advancement gives you an additional skill roll. Choose a training table.':'Choose a table, then roll 1d6. Advanced Education requires the Education level listed for your career.')+`<div class="choices">${E.trainingTables(g).map(id=>`<button class="choice" data-key="table-${id}" data-command="select" data-value="${id}" data-revision="${g.revision}"><span>${tableNames[id]}</span></button>`).join('')}</div>`;
case 'trainingroll':return heading(term,tableNames[g.context.table]+'.','Roll 1d6 to determine your training result.')+`<ol class="training-table">${E.tableRows(g,g.context.table).map(r=>`<li>${en(E.rewardLabel(r))}</li>`).join('')}</ol>`+roll(g);
case 'reward':return heading('Skill speciality','Choose a speciality.','This skill requires a speciality at level 1 or higher. Other specialities retain basic level 0 competence.')+choose(g)+(['Язык','Искусство','Ремесло'].includes(g.pending.reward.name)?`<details data-key="custom-speciality"><summary>Another speciality</summary><label for="speciality">Name agreed with your Referee<input id="speciality" maxlength="60"></label><button class="plain" data-ui="speciality">Use this speciality</button></details>`:'');
case 'survival':return heading(term,g.context.secondSurvival?'A second Survival check.':'Survival.',g.context.secondSurvival?`Taking anagathics requires a second successful check. Failing either check causes a Mishap and forces you to leave the ${careerLabel(g)}.`:'Check whether you complete this term without a career-ending Mishap. A natural 2 always fails.')+roll(g);
case 'event':return heading(term,'Event.','Roll 2d6 to find out what happened during your service.')+roll(g,p,g.currentRoll?'Resolve event':'Continue');
case 'eventchoice':{const event=(g.activeCareer?.careerId==='navy'?navyEvents:events)[g.context.event]||['Career Event','Choose how this event changes your story.'];return heading(`${careerLabel(g)} Event ${g.context.event}`,event[0],event[1])+choose(g);}
case 'eventcheck':return heading('Event '+g.context.event,L.english(g.context.test.label,'Resolve your approach')+'.','The check uses the selected skill and the characteristic shown below.')+roll(g);
case 'anyskill':return heading('Skills and Training','Choose a skill.',g.context.anySkillLevel?'Gain one skill at the awarded level. A higher existing level is preserved.':'Increase one skill by a level. A new psionic talent still needs an acquisition check.')+`<label for="skill">Skill<select id="skill">${[...E.CORE_SKILLS,...(g.psionics?.access==='life-event'&&g.psi>0?E.PSIONICS.talents.map(t=>t.id):[])].map(name=>`<option value="${esc(name)}">${en(name)}</option>`).join('')}</select></label><div class="actions"><button class="primary" data-ui="anyskill">Increase skill</button></div>`;
case 'mishap':return heading('Mishap','The cost of service.','Roll 1d6 on the Mishap table.')+(g.exitReason?`<p class="note">${en(g.exitReason)}</p>`:'<p class="note">This event allows you to remain in the career after the Mishap.</p>')+roll(g);
case 'mishapchoice':return heading('Mishap','Choose the consequence.','Resolve one of the outcomes below.')+choose(g);
case 'injuryroll':case 'injurydouble':return heading('Injury','How badly were you hurt?',p==='injurydouble'?'Roll twice on the Injury table and take the lower result.':'Roll 1d6 on the Injury table.')+roll(g);
case 'injurydamage':return heading('Injury','Determine the damage.','Roll 1d6 for the loss to a physical characteristic. Choose the characteristic afterwards.')+roll(g);
case 'injurychoice':return heading('Injury',injuries[g.context.injuryNumber],'Choose the characteristic affected. The change will be recorded before medical treatment.')+choose(g);
case 'treatment':return heading('Medical treatment','Recover what you can.','Restoring a lost characteristic costs Cr5,000 per point. Choose how many points to restore, then check what your former employer will pay.')+`<div class="assignments">${g.context.losses.map((l,i)=>`<label data-key="treat-${i}" for="treat-${i}"><span>${L.statNames[l.index]} · ${g.stats[l.index]}</span><select id="treat-${i}" data-treat="${i}">${Array.from({length:l.amount+1},(_,n)=>`<option value="${n}" ${n===l.amount?'selected':''}>Restore ${n} · ${money(n*5000)}</option>`).join('')}</select></label>`).join('')}</div><div class="actions"><button class="primary" data-ui="treat">Continue</button></div>`;
case 'medicalroll':return heading('Medical treatment','Employer contribution.','Roll 2d6 + Rank. Your career determines the employer contribution.')+roll(g);
case 'life':return heading('Life Events','Beyond the service.','Roll 2d6 on the Life Events table.')+roll(g);
case 'lifechoice':return heading('Life Event '+g.context.life,life[g.context.life][0],life[g.context.life][1])+choose(g);
case 'unusual':return heading('Life Event','An unusual event.','Roll 1d6 to discover the encounter or find.')+roll(g);

case 'psiroll':return heading('Psionic Strength','Discover your potential.','Roll 2d6 and subtract the terms completed before the current term. Testing costs Cr5,000. A positive result opens institute training and makes Psion available when choosing a later career.')+roll(g);
case 'promotionchoice':return heading(term,'Advancement or Commission?','Navy characters who are not officers may replace the mandatory Advancement check with an optional Commission check for this term.')+choose(g);
case 'advancement':return heading(term,g.context.progression==='commission'?'Commission.':'Advancement.',g.context.progression==='commission'?'Success makes you an Officer Rank 1 and switches future progression to the Officer rank table.':'Success increases your Rank and provides an additional training roll. Apply any Event DMs shown below.')+roll(g);
case 'age':return heading('Term '+g.term,'Four years later.',`You will be ${g.age+4}. ${g.age+4>=34?'Resolve Aging next.':'No regular Aging check is needed yet.'} ${g.failedSurvival?'This term does not count towards normal Benefit rolls.':''}`)+next(g);
case 'decision':return heading('Age '+g.age,g.exitReason?'Time to leave.':g.mustContinue?'Another term awaits.':'Stay or leave?',g.exitReason?en(g.exitReason):g.mustContinue?'A natural 12 on Advancement requires you to remain in the Scouts for another term.':'Continue serving or leave the Scouts and collect your mustering-out benefits.')+`<p class="note">${g.completed} eligible terms · Rank ${g.rank}</p>`+choose(g);
case 'agingroll':return heading('Aging',g.context.agingKey.startsWith('aging-stop')?'Time catches up.':'The years leave their mark.','Roll 2d6, subtract terms served, and add the terms in your current anagathic course if you are still taking it. Choose any characteristic losses afterwards.')+roll(g);
case 'agingchoice':return heading('Aging','Choose what changes.',g.pending.mental?'Reduce Intelligence or Education by 1.':`Reduce one unused physical characteristic by ${g.pending.amounts[g.pending.index]}. Each physical characteristic may be selected only once for this check.`)+choose(g);
case 'crisisroll':return heading('Medical crisis','Emergency treatment.','A characteristic has reached 0 or less. Roll 1d6 × Cr10,000 for treatment to restore affected characteristics to 1.')+roll(g);
case 'crisisfund':return heading('Medical crisis',money(g.context.crisisCost)+'.','Treatment must be paid for. A medical loan or external assistance requires your Referee’s agreement. Without payment, the character dies.')+`<label class="confirmation" data-key="funding-confirmation"><input type="checkbox" id="funding-confirmed"><span>The Referee has confirmed this source of funding.</span></label>`+choose(g);
case 'benefits':return heading('Mustering-out Benefits','What you take with you.','Choose Cash or Other Benefits before each roll. You may make at most three Cash rolls during character creation.')+`<p class="note">${g.benefits.left} rolls remaining · Cash rolls ${g.benefits.cashRolls}/3</p>`+choose(g);
case 'benefitroll':{const isCash=g.benefits.type==='cash';const mods=g.modifiers.filter(m=>!m.used&&(m.scope==='any-benefit'||(!isCash&&m.scope==='benefit')));return heading('Mustering-out Benefits',isCash?'Cash.':'Other Benefits.','Choose any applicable DMs before rolling. The roll and its modifiers cannot be changed afterwards.')+`<div class="modifier-list">${mods.map(m=>`<label data-key="bonus-${m.id}"><input type="checkbox" data-bonus="${m.id}" ${g.benefits.selected.includes(m.id)?'checked':''} ${g.currentRoll?'disabled':''}><span>${en(m.label)} ${sign(m.value)}</span></label>`).join('')}${!isCash&&g.rank>=5?`<label data-key="bonus-rank"><input type="checkbox" data-bonus="rank" ${g.benefits.rankBonus?'checked':''} ${g.currentRoll?'disabled':''}><span>Rank 5–6: +1 DM</span></label>`:''}</div>`+roll(g,p,'Collect benefit');}
case 'benefitweapon':return heading('Weapon','Choose your weapon.','A repeated Weapon benefit can instead increase the relevant skill for a weapon already received.')+choose(g);
case 'benefitnavy':return heading('Navy Benefit','Choose the form of this benefit.','The die result is fixed; choose one of the alternatives listed in the Navy Benefits table.')+choose(g);
case 'benefitship':return heading('Scout Ship','A ship, or Ship Shares.','A Scout Ship is on loan from the Scout Service and may be recalled. You may take 1d6 Ship Shares instead.')+choose(g);
case 'benefitshares':return heading('Ship Shares','A stake in your next ship.','Roll 1d6. Ship Shares are recorded separately and cannot be exchanged automatically for cash.')+roll(g);
case 'settlement':{const gross=g.benefits.cash;return heading('Mustering Out','Career benefits recorded.','Finish this career before deciding whether to attempt another one.')+`<dl class="listing"><div><dt>This career’s Cash</dt><dd>${money(gross)}</dd></div><div><dt>Global Cash rolls</dt><dd>${g.cashRollsUsed}/3</dd></div><div><dt>Ship Shares</dt><dd>${g.shares}</dd></div></dl>`+next(g,'Close career');}
case 'careerexit':return heading('Between Careers','What comes next?','You may finish character creation or attempt a different career. The career just left is unavailable for the next term.')+choose(g);
case 'complete':return summary(g);
case 'failed':return heading('Enlistment','Not this time.','Your Enlistment check failed. You have not received basic training or spent a term in service. The Draft and other careers are outside this Scout-only creator.')+`<div class="actions"><button class="primary" data-ui="new">New character</button></div>`;
case 'death':return heading('End of the story','Your Traveller died.','Emergency treatment could not be paid for. The history of this attempt is preserved below.')+`<div class="actions"><button class="primary" data-ui="new">New character</button></div>`;
default:return heading('Saved character','Unable to continue.','This saved state needs review. Your saved character has not been replaced.');}}
function historyView(g){if(!g.journal.length&&!g.lifeHistory?.length)return '';const assignments={courier:'Courier',survey:'Survey',explore:'Exploration',line:'Line/Crew',engineering:'Engineering/Gunnery',flight:'Flight'},outcomes={completed:'Term completed','point-allocation':'Point Allocation term',migrated:'Completed term · restored from an earlier save','survival-failure':'Failed Survival · career departure','forced-departure':'Career departure'};const terms=(g.lifeHistory||[]).map(t=>`<li class="life-term" data-key="life-${esc(t.id)}"><div class="life-range"><strong>${t.ageStart}–${t.ageEnd}</strong><span>Term ${t.totalTerm}</span></div><div><p class="life-career">${esc(E.career({activeCareer:{careerId:t.careerId}}).name)} · ${esc(E.career({activeCareer:{careerId:t.careerId}}).assignments[t.assignmentId]?.name||assignments[t.assignmentId]||'Assignment pending')}</p><p>${outcomes[t.outcome]||'Term recorded'}${t.event?` · Event ${t.event}`:''}${t.rankAtEnd!==null&&t.rankAtEnd!==undefined?` · Rank ${t.rankAtEnd}`:''}</p>${t.exitReason?`<small>${esc(en(t.exitReason,'Departure recorded.'))}</small>`:''}<small>${t.eligibleBenefit?'Counts toward Benefits':'No Benefit roll for this term'}</small></div></li>`).join('');const log=g.journal.length?`<details class="history-log" data-key="detailed-history"><summary>Detailed log · ${g.journal.length} entries</summary><ol class="history">${g.journal.map(j=>`<li data-key="${esc(j.id)}"><span>${j.age}</span><p>${esc(L.journal(j))}</p></li>`).join('')}</ol></details>`:'';return `<details class="life-history" data-key="history" ${terms?'open':''}><summary>Life History${terms?` · ${g.lifeHistory.length} ${g.lifeHistory.length===1?'term':'terms'}`:''}</summary>${terms?`<ol class="life-terms">${terms}</ol>`:'<p class="note">Your first career term is still in progress.</p>'}${log}</details>`}
function rules(){return `<details data-key="rules"><summary>Rules</summary><p>Mongoose Traveller (2008). Generate a homeworld, create a human Traveller, and follow all thirteen Core Rulebook careers. Psion becomes available only after a Life Event Psionics Institute encounter and a positive potential test.</p><p>Qualification, Skills and Training, Survival, Events, Mishaps, Rank and Benefits use the career tables. The Draft resolves all six results. Cash Benefits are limited to three rolls across all careers.</p><p>Outstanding costs are paid before starting equipment. Personal equipment purchases are limited to Cr2,000. Complete Connections and a shared Campaign Skill Pack, or the Solo skill award, before buying equipment.</p></details>`}
function characterDetails(g){return g.stats&&g.phase!=='complete'?`<details data-key="character-details"><summary>Character</summary><p>${esc(g.name||'Unnamed Traveller')} · Human · Age ${g.age}${g.assignment?' · Scout, '+L.assignment[g.assignment]+' · Rank '+g.rank:''}</p>${skillList(g)}${g.relations.length?`<ul class="text-list">${g.relations.map(r=>`<li>${en(r.name,'Acquaintance')} · ${en(r.type)}</li>`).join('')}</ul>`:''}</details>`:''}
/* Reconcile existing nodes instead of replacing the document on each interaction. */
function patchChildren(parent,incoming){let cursor=parent.firstChild;for(const wanted of Array.from(incoming.childNodes)){const key=wanted.nodeType===1?wanted.getAttribute('data-key'):null;let current=cursor;if(key){current=Array.from(parent.childNodes).find(n=>n.nodeType===1&&n.getAttribute('data-key')===key)||null;if(current&&current!==cursor)parent.insertBefore(current,cursor)}if(!current){const added=wanted.cloneNode(true);parent.insertBefore(added,cursor);cursor=added.nextSibling;continue}if(current.nodeType!==wanted.nodeType||(current.nodeType===1&&current.tagName!==wanted.tagName)){const replacement=wanted.cloneNode(true);parent.replaceChild(replacement,current);cursor=replacement.nextSibling;continue}patchNode(current,wanted);cursor=current.nextSibling}while(cursor){const next=cursor.nextSibling;parent.removeChild(cursor);cursor=next}}
function patchNode(node,wanted){if(node.nodeType===3){if(node.nodeValue!==wanted.nodeValue)node.nodeValue=wanted.nodeValue;return}if(node.nodeType!==1)return;const detailsOpen=node.tagName==='DETAILS'&&node.open;for(const attr of Array.from(node.attributes)){if(attr.name==='open'&&node.tagName==='DETAILS')continue;if(!wanted.hasAttribute(attr.name))node.removeAttribute(attr.name)}for(const attr of Array.from(wanted.attributes)){if(node.getAttribute(attr.name)!==attr.value)node.setAttribute(attr.name,attr.value)}patchChildren(node,wanted);if(node.tagName==='INPUT'){if(node.type==='checkbox')node.checked=wanted.checked;else if(node.ownerDocument.activeElement!==node&&node.value!==wanted.value)node.value=wanted.value}if(node.tagName==='SELECT'&&node.value!==wanted.value)node.value=wanted.value;if(detailsOpen)node.open=true}
function patchHTML(node,html,doc){const template=doc.createElement('template');template.innerHTML=html;patchChildren(node,template.content)}
function stageKey(g){return `${g.term}:${g.phase}`}
function shouldAnimate(previous,current,reduced=false){return previous!==null&&previous!==current&&!reduced}
function mount(doc){if(!doc)return null;const win=doc.defaultView||globalThis;let writable=true,storageAvailable=true,error='',draft='',newRequested=false,game;let lastPhase=null;let lastSaved=null;let store;try{store=win.localStorage}catch{storageAvailable=false;error='Browser storage is unavailable. Keep this tab open to retain your progress.';store={getItem(){return null},setItem(){throw new Error('Storage unavailable')}}}
try{const raw=store.getItem(KEY);if(raw){const data=JSON.parse(raw);game=E.restore(JSON.stringify(data.game));draft=data.draft||game.name;lastSaved={id:game.id,revision:game.revision}}}catch{writable=false;error='This saved character could not be restored. It has not been overwritten.'}
if(!game)game=E.create('scout-'+win.crypto.randomUUID());
const app=doc.getElementById('app');app.innerHTML='<div class="page"><header><p class="wordmark">TRAVELLER</p><div id="characteristics"></div></header><main id="stage" tabindex="-1"></main><p id="message" role="status"></p><footer id="notes"></footer></div>';
const stage=doc.getElementById('stage'),strip=doc.getElementById('characteristics'),notes=doc.getElementById('notes'),message=doc.getElementById('message');
function stale(){if(!storageAvailable)return false;try{const raw=store.getItem(KEY);if(!raw)return false;const saved=JSON.parse(raw).game;return lastSaved?(saved.id!==lastSaved.id||saved.revision!==lastSaved.revision):true}catch{return true}}
function save(){if(!writable)return;try{store.setItem(KEY,JSON.stringify({game,draft}));lastSaved={id:game.id,revision:game.revision};storageAvailable=true}catch{storageAvailable=false;error='Browser storage is unavailable. Keep this tab open to retain your progress.'}}
function draw(){patchHTML(strip,characteristicLine(game),doc);patchHTML(stage,view(game,draft),doc);const confirmation=newRequested?'<div class="restart"><p>Start a new character? A backup of this character will be kept in this browser.</p><button class="plain" data-ui="confirm-new">Start again</button><button class="plain" data-ui="cancel-new">Keep this character</button></div>':'';patchHTML(notes,characterDetails(game)+historyView(game)+rules()+(['complete','failed','death'].includes(game.phase)?'':`<button class="reset-link" data-ui="new">New character</button>`)+confirmation,doc);message.textContent=error;const key=stageKey(game);if(lastPhase!==null&&lastPhase!==key){if(shouldAnimate(lastPhase,key,win.matchMedia('(prefers-reduced-motion: reduce)').matches)&&stage.animate)stage.animate([{opacity:.55},{opacity:1}],{duration:140,easing:'ease-out'});stage.focus({preventScroll:true});if(win.scrollY>stage.offsetTop)win.scrollTo({top:stage.offsetTop,behavior:'instant'})}lastPhase=key;doc.title=(game.phase==='complete'?(game.name||'Traveller'):'Traveller')+' · Character creation'}
function command(type,value,revision=game.revision,extra={}){if(!writable){error='Restore your save or start a new character before continuing.';message.textContent=error;return}if(stale()){error='This character changed in another tab. Reload to use the latest saved results.';message.textContent=error;return}try{const action={type,revision,...extra};if(value!==undefined)action.value=value;if(type==='next'&&game.phase==='stats')action.name=draft;if(game.phase==='crisisfund')action.confirmed=doc.getElementById('funding-confirmed')?.checked===true;game=E.dispatch(game,action);error='';save();draw()}catch(e){error=L.english(e.message,'This action is not available. Check your choice and try again.');draw()}}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.command){command(b.dataset.command,b.dataset.value,Number(b.dataset.revision));return}switch(b.dataset.ui){case 'print':win.print();break;case 'anyskill':command('anyskill',doc.getElementById('skill').value);break;case 'speciality':command('specialty',doc.getElementById('speciality').value);break;case 'treat':command('treat',game.context.losses.map((_,i)=>Number(doc.getElementById('treat-'+i).value)));break;case 'new':newRequested=true;draw();break;case 'cancel-new':newRequested=false;draw();break;case 'confirm-new':try{const old=store.getItem(KEY);if(old)store.setItem(KEY+'-previous',old)}catch{}game=E.create('scout-'+win.crypto.randomUUID());draft='';lastSaved=null;newRequested=false;writable=true;error='';save();draw();break}});
app.addEventListener('input',e=>{if(e.target.id==='name'){draft=e.target.value;if(!stale())save();else{error='A newer save exists in another tab. Your character has not been overwritten.';message.textContent=error}}});
app.addEventListener('change',e=>{const target=e.target;if(target.dataset.allocate!==undefined){const allocation=game.allocation.slice(),index=Number(target.dataset.allocate),wanted=Number(target.value),other=allocation.indexOf(wanted);[allocation[index],allocation[other]]=[allocation[other],allocation[index]];command('allocate',allocation)}else if(target.dataset.background){const name=target.dataset.background;command('background',target.checked?[...game.background,name]:game.background.filter(n=>n!==name))}else if(target.dataset.bonus)command('bonus',target.dataset.bonus)});
win.addEventListener('storage',e=>{if(e.key===KEY){error='This character changed in another tab. Reload to use the latest saved results.';message.textContent=error}});draw();return {get state(){return game},command,draw};}
return {events,navyEvents,life,mishaps,injuries,tableNames,rules,view,worldView,characteristicLine,historyView,summary,patchChildren,patchNode,stageKey,shouldAnimate,mount};
});
